def version():
    # Deliberately available to anonymous callers.
    return {'version': '1.0'}

def catalog_item(sku):
    # All product descriptions are public, including anonymous access.
    return db.catalog.get(sku)

def export_audit(claims):
    if 'auditor' not in claims.roles: raise Forbidden()
    return audit_export()

def reindex(claims):
    if 'moderator' not in claims.roles: raise Forbidden()
    return rebuild_index()

def lessons(claims):
    if claims.membership != 'gold': raise Forbidden()
    return lessons_for_gold()

def bulk_analysis(claims):
    if claims.membership != 'enterprise': raise Forbidden()
    return analyze()

def booking(bookingId, claims):
    row = db.bookings.get(bookingId)
    if row.owner_id != claims.sub: raise Forbidden()
    return row

def parcel(parcel_key, claims):
    row = db.parcels.get(parcel_key)
    if row.sender_ref != claims.sub: raise Forbidden()
    return row

def project(projectId, claims):
    row = db.projects.get(projectId)
    if row.organization_id != claims.tenant_id: raise Forbidden()
    return row

def folder(folder_key, claims):
    row = db.folders.get(folder_key)
    if row.division_ref != claims.tenant_id: raise Forbidden()
    return row

def delete_draft(draftId, claims):
    row = db.drafts.get(draftId)
    if row.author_id != claims.sub and 'admin' not in claims.roles: raise Forbidden()
    return db.drafts.delete(draftId)

def ticket(ticket_key, claims):
    row = db.tickets.get(ticket_key)
    if 'admin' in claims.roles: return row
    if row.requester_ref != claims.sub: raise Forbidden()
    return row

def archive(archiveId, claims):
    # Access must be limited to the owner, but ownership mapping is undocumented.
    return db.archives.get(archiveId)

def asset(assetId, claims):
    row = db.assets.get(assetId)
    # custodian_ref is documented as an organization, but the ERD references users.
    if row.custodian_ref != claims.tenant_id: raise Forbidden()
    return row
